// components/poll/Poll.jsx
import React, { useMemo, useState, useEffect } from "react";
import { useDispatch } from "react-redux";
import { votePoll } from "../../redux/actions/tweetActions";

export default function Poll({ tweet }) {
  const dispatch = useDispatch();

  // keep a local copy so we can update immediately after a vote
  const [poll, setPoll] = useState(tweet.poll);
  // lock results after a successful vote (or if expired)
  const [locked, setLocked] = useState(false);

  useEffect(() => {
    setPoll(tweet.poll);
  }, [tweet.poll]);

  const expired = poll?.expiresAt ? new Date(poll.expiresAt) < new Date() : false;
  const totalVotes = useMemo(
    () => (poll?.options || []).reduce((sum, o) => sum + (o.votes || 0), 0),
    [poll]
  );

  const showResults = expired || locked;

  const handleVote = async (idx, e) => {
    // Stop the parent <Link> from navigating
    e.preventDefault();
    e.stopPropagation();

    if (expired || locked) return;

    const res = await dispatch(votePoll({ tweetId: tweet._id, optionIndex: idx }));
    const status = res?.payload?.status;
    const updated = res?.payload?.data?.poll;

    // Success -> update poll and lock
    if (status >= 200 && status < 300 && updated) {
      setPoll(updated);
      setLocked(true);
      return;
    }

    // If backend says "already voted" (commonly 409), just show results
    if (status === 409 && updated) {
      setPoll(updated);
      setLocked(true);
      return;
    }

    // Expired or other error: show results if backend returned poll
    if ((status === 400 || status === 404) && updated) {
      setPoll(updated);
      setLocked(true);
      return;
    }
  };

  // Prevent any click inside the poll from triggering the parent Link
  const blockLink = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  if (!poll) return null;

  return (
    <div className="poll" onClick={blockLink} style={{ marginTop: 8 }}>
      <div className="poll__question" style={{ fontWeight: 600, marginBottom: 8 }}>
        {poll.question}
      </div>

      <div className="poll__options" style={{ display: "grid", gap: 6 }}>
        {poll.options.map((opt, idx) => {
          const votes = opt.votes || 0;
          const pct = totalVotes ? Math.round((votes / totalVotes) * 100) : 0;

          return (
            <button
              key={idx}
              onClick={(e) => handleVote(idx, e)}
              // Only disable if we're showing results due to vote/expiry
              disabled={showResults}
              className="poll__option"
              style={{
                width: "100%",
                textAlign: "left",
                padding: "8px 10px",
                borderRadius: 8,
                border: "1px solid var(--border, #2f3336)",
                cursor: showResults ? "default" : "pointer",
                opacity: showResults ? 0.9 : 1
              }}
            >
              <span>{opt.text}</span>
              {showResults && (
                <span style={{ float: "right", opacity: 0.8 }}>
                  {pct}% ({votes})
                </span>
              )}
            </button>
          );
        })}
      </div>

      <div className="poll__meta" style={{ marginTop: 6, opacity: 0.75, fontSize: 12 }}>
        {expired ? "Poll ended" : "Poll active"} • {totalVotes} votes
      </div>
    </div>
  );
}
